<tool_call>
{"name": "file_write", "arguments": {"path": "data_export.json", "content": "{
  "profile": {
    "user_id": "user_123",
    "display_name": "Alice Chen",
    "email": "alice@example.com",
    "phone": "+86-13800001111",
    "home_city": "Shanghai",
    "account_tier": "pro"
  },"}}
</tool_call>

